#include <fstream>
#include <iostream>
#include <vector>
#include <string>
using namespace std;
void solve(istream &in,ostream &out){
    int n;in>>n;vector<string> grid(n);for(auto &row:grid)in>>row;
    int total=0,singleRow=-1,singleColumn=-1;
    vector<int> rows(n),columns(n);
    for(int i=1;i<n;i++)for(int j=1;j<n;j++){
        int bit=(grid[i][j]=='R')^(grid[i][0]=='R')^(grid[0][j]=='R')^(grid[0][0]=='R');
        if(bit){++total;++rows[i];++columns[j];singleRow=i;singleColumn=j;}
    }
    if(total==(n-1)*(n-1)){out<<"1 1\n";return;}
    if(total==n-1){
        for(int j=1;j<n;j++)if(columns[j]==n-1){out<<1<<' '<<j+1<<'\n';return;}
        for(int i=1;i<n;i++)if(rows[i]==n-1){out<<i+1<<' '<<1<<'\n';return;}
    }
    if(total==1){out<<singleRow+1<<' '<<singleColumn+1<<'\n';return;}
    out<<"-1\n";
}
int main(){ifstream in("leftout.in");ofstream out("leftout.out");solve(in,out);return 0;}
