using Wide=__int128_t;
struct Point{long long x,y;};
struct Segment{Point a,b;};
Wide cross(Point a,Point b,Point c){return Wide(b.x-a.x)*(c.y-a.y)-Wide(b.y-a.y)*(c.x-a.x);}
int sign(Wide v){return (v>0)-(v<0);}
bool intersects(const Segment &u,const Segment &v){
    if(max(min(u.a.x,u.b.x),min(v.a.x,v.b.x))>min(max(u.a.x,u.b.x),max(v.a.x,v.b.x)))return false;
