// Explicit AVL order: no std::set comparator depending on a mutable sweep x.
// Before a detected intersection, the in-order active sequence cannot swap.
class SweepOrder{
    struct Node{int id=-1,left=-1,right=-1,parent=-1,height=1;};
    vector<Node> node;vector<int> where;const vector<Segment>&segment;int root=-1;long long x=0;
    int height(int u)const{return u<0?0:node[u].height;}
    void update(int u){node[u].height=1+max(height(node[u].left),height(node[u].right));}
    void attach(int parent,int oldChild,int newChild){
        if(parent<0)root=newChild;
        else if(node[parent].left==oldChild)node[parent].left=newChild;
        else node[parent].right=newChild;
        if(newChild>=0)node[newChild].parent=parent;
    }
    int rotateLeft(int u){
        int v=node[u].right,p=node[u].parent,middle=node[v].left;
        attach(p,u,v);node[v].left=u;node[u].parent=v;node[u].right=middle;if(middle>=0)node[middle].parent=u;update(u);update(v);return v;
    }
    int rotateRight(int u){
        int v=node[u].left,p=node[u].parent,middle=node[v].right;
        attach(p,u,v);node[v].right=u;node[u].parent=v;node[u].left=middle;if(middle>=0)node[middle].parent=u;update(u);update(v);return v;
    }
    void rebalance(int u){
        while(u>=0){
            update(u);int balance=height(node[u].left)-height(node[u].right);
            if(balance>1){int v=node[u].left;if(height(node[v].left)<height(node[v].right))rotateLeft(v);u=rotateRight(u);}
            else if(balance< -1){int v=node[u].right;if(height(node[v].right)<height(node[v].left))rotateRight(v);u=rotateLeft(u);}
            u=node[u].parent;
        }
    }
    pair<Wide,long long> ordinate(int id)const{
        const auto &s=segment[id];long long dx=s.b.x-s.a.x;
        return {Wide(s.a.y)*dx+Wide(s.b.y-s.a.y)*(x-s.a.x),dx};
    }
    bool below(int a,int b)const{
        auto [an,ad]=ordinate(a);auto [bn,bd]=ordinate(b);Wide delta=an*bd-bn*ad;
        return delta!=0?delta<0:a<b;
    }
public:
    SweepOrder(const vector<Segment>&s):node(s.size()),where(s.size(),-1),segment(s){}
    void setX(long long value){x=value;}
    int predecessor(int id)const{
        int u=where[id];if(node[u].left>=0){u=node[u].left;while(node[u].right>=0)u=node[u].right;return node[u].id;}
        int p=node[u].parent;while(p>=0&&node[p].left==u){u=p;p=node[u].parent;}return p<0?-1:node[p].id;
