    int successor(int id)const{
        int u=where[id];if(node[u].right>=0){u=node[u].right;while(node[u].left>=0)u=node[u].left;return node[u].id;}
        int p=node[u].parent;while(p>=0&&node[p].right==u){u=p;p=node[u].parent;}return p<0?-1:node[p].id;
