        while(current>=0){parent=current;goLeft=below(id,node[current].id);current=goLeft?node[current].left:node[current].right;}
        node[id]=Node{};node[id].id=id;node[id].parent=parent;where[id]=id;
        if(parent<0)root=id;else if(goLeft)node[parent].left=id;else node[parent].right=id;rebalance(parent);
    }
    void erase(int id){
        int u=where[id];where[id]=-1;
        if(node[u].left>=0&&node[u].right>=0){
            int v=node[u].right;while(node[v].left>=0)v=node[v].left;
            node[u].id=node[v].id;where[node[u].id]=u;u=v;
