pair<int,int> findIntersection(const vector<Segment>&s){
    vector<tuple<long long,int,int>> events;
    for(int i=0;i<int(s.size());i++){
        if(s[i].a.x==s[i].b.x)events.push_back({s[i].a.x,1,i});
        else{events.push_back({s[i].a.x,0,i});events.push_back({s[i].b.x,2,i});}
    }
    sort(events.begin(),events.end());SweepOrder active(s);
    for(size_t start=0;start<events.size();){
        size_t end=start;long long x=get<0>(events[start]);while(end<events.size()&&get<0>(events[end])==x)++end;active.setX(x);
        vector<int> vertical,ending;
        for(size_t k=start;k<end;k++){
            auto [unused,kind,id]=events[k];(void)unused;
            if(kind==0){active.insert(id);int a=active.predecessor(id),b=active.successor(id);if(a>=0&&intersects(s[a],s[id]))return {a,id};if(b>=0&&intersects(s[b],s[id]))return {b,id};}
            else if(kind==1)vertical.push_back(id);else ending.push_back(id);
        }
        sort(vertical.begin(),vertical.end(),[&](int a,int b){return min(s[a].a.y,s[a].b.y)<min(s[b].a.y,s[b].b.y);});
        long long high=-1;int previous=-1;
        for(int id:vertical){
            long long low=min(s[id].a.y,s[id].b.y),top=max(s[id].a.y,s[id].b.y);
            if(previous>=0&&low<=high)return {previous,id};
            if(top>high){high=top;previous=id;}
            int candidate=active.firstAtLeast(low);if(candidate>=0&&active.atMost(candidate,top))return {candidate,id};
        }
        for(int id:ending){int a=active.predecessor(id),b=active.successor(id);active.erase(id);if(a>=0&&b>=0&&intersects(s[a],s[b]))return {a,b};}
        start=end;
    }
    return {-1,-1};
}
void solve(istream &in,ostream &out){
    int n;in>>n;vector<Segment>s(n);
    for(auto &v:s){in>>v.a.x>>v.a.y>>v.b.x>>v.b.y;if(v.a.x>v.b.x)swap(v.a,v.b);}
    auto [a,b]=findIntersection(s);
    // The source guarantees an intersection and a single successful removal.
    bool moreA=false,moreB=false;
    for(int i=0;i<n;i++)if(i!=a&&i!=b){moreA|=intersects(s[a],s[i]);moreB|=intersects(s[b],s[i]);}
    out<<(moreA?a:moreB?b:min(a,b))+1<<'\n';
}
