#include <fstream>
#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>
#include <climits>
using namespace std;
void solve(istream &in,ostream &out){
    int n,m;in>>n>>m;vector<pair<long long,long long>> point(n);
    for(auto &[x,y]:point)in>>x>>y;
    vector<vector<int>> graph(n);
    for(int i=0;i<m;i++){int a,b;in>>a>>b;--a;--b;graph[a].push_back(b);graph[b].push_back(a);}
    vector<unsigned char> seen(n,0);long long answer=LLONG_MAX;
    for(int root=0;root<n;root++)if(!seen[root]){
        vector<int> stack(1,root);seen[root]=1;
        long long loX=point[root].first,hiX=loX,loY=point[root].second,hiY=loY;
        while(!stack.empty()){
            int u=stack.back();stack.pop_back();auto [x,y]=point[u];
            loX=min(loX,x);hiX=max(hiX,x);loY=min(loY,y);hiY=max(hiY,y);
            for(int v:graph[u])if(!seen[v]){seen[v]=1;stack.push_back(v);}
        }
        answer=min(answer,2*(hiX-loX+hiY-loY));
    }
    out<<answer<<'\n';
}
int main(){ifstream in("fenceplan.in");ofstream out("fenceplan.out");solve(in,out);return 0;}
